def _write_anchor_key_file(path: str, material: bytes) -> None:
    """Create the anchor-key sidecar atomically, with owner-only mode.

    The material is written to a unique temporary file, flushed, and
    then hard-linked into place: the link is atomic and fails with
    :class:`FileExistsError` when another creator won, so a reader can
    never observe a half-written key. Every filesystem failure becomes
    the fixed-text storage error; the key bytes themselves are never
    placed in that error or a log.
    """
    tmp_path = "%s.%s.tmp" % (path, uuid.uuid4().hex)
    try:
        fd = os.open(
            tmp_path,
            os.O_WRONLY | os.O_CREAT | os.O_EXCL,
            0o600,
        )
    except OSError:
        raise _storage_failure() from None
    try:
        written = 0
        while written < len(material):
            written += os.write(fd, material[written:])
        os.fsync(fd)
    except OSError:
        raise _storage_failure() from None
    finally:
        try:
            os.close(fd)
        except OSError:
            raise _storage_failure() from None
    try:
        # Atomic create-if-absent: never truncates a winner's key.
        os.link(tmp_path, path)
    except FileExistsError:
        raise
    except OSError:
        raise _storage_failure() from None
    finally:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass

